namespace Tiki\Build;

/**
 * Reads the Vite manifest to resolve source paths to their versioned (content-hashed) output filenames.
 *
 * The manifest is generated by `vite build` at public/generated/js/.vite/manifest.json
 * and maps source paths (relative to project root) to their built output files.
 */
class ViteManifest
{
    private static ?array $manifest = null;

    /**
     * Resolve a source file path to its versioned output path.
     *
     * @param string $path File path relative to project root, e.g. "themes/sands/options/e-compliance/js/custom.module.js"
     *                     or a public path like "public/generated/_custom/shared/js/custom.module.js"
     * @return string|null The versioned output path relative to project root, or null if not found in the manifest
     */
    public static function resolve(string $path): ?string
    {
        self::loadManifest();
        if (isset(self::$manifest[$path])) {
            return JS_ASSETS_PATH . '/' . self::$manifest[$path]['file'];
        }
        $prefix = PUBLIC_GENERATED_PATH . '/';
        if (str_starts_with($path, $prefix)) {
            $srcPath = substr($path, strlen($prefix));
            if (isset(self::$manifest[$srcPath])) {
                return JS_ASSETS_PATH . '/' . self::$manifest[$srcPath]['file'];
            }
        }
        return null;
    }

    private static function loadManifest(): void
    {
        if (self::$manifest !== null) {
            return;
        }
        $manifestPath = JS_ASSETS_PATH . '/.vite/manifest.json';
        if (is_file($manifestPath)) {
            self::$manifest = json_decode(file_get_contents($manifestPath), true) ?: [];
        } else {
            self::$manifest = [];
        }
    }
}
